package com.rpsbattle.tournament;

import com.rpsbattle.tournament.coding.*;
import com.rpsbattle.tournament.domain.*;
import com.rpsbattle.codevalidation.BotTestService;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.context.TestPropertySource;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@TestPropertySource(properties="rps.coding.worker-auto-dispatch=false")
class FinalValidationApiTest extends TimelineDeadlineApiTest {
 @Test void officialValidationNoticeIsPersonalAndCannotExposeHiddenDetails()throws Exception{String base=exam("DISQUALIFY");ready(base,130);freeze(base);enqueue(base);finalDone(base);assertThat(request(base+"/notifications","GET",null,200).toString()).contains("TIMELINE_BOT_VALIDATION_PASSED").doesNotContain("sourceCode","sourceHash","artifactHash","Hidden Test","reason");request("/api/auth/logout","POST",Map.of(),200);account=null;loginAccount();request(base+"/notifications","GET",null,403);}
 @Test void timelineCheckInUsesExactServerWindowAndIsIdempotent()throws Exception{
  String base=exam("DISQUALIFY");ready(base,130);freeze(base);enqueue(base);finalDone(base);
  when(clock.instant()).thenReturn(START.plusSeconds(600).minusNanos(1));request(base+"/check-in","POST",Map.of(),400);
  when(clock.instant()).thenReturn(START.plusSeconds(600));var flow=request(base+"/participant-flow","GET",null,200);assertThat(flow.path("nextAction").asText()).isEqualTo("CHECK_IN");
  request(base+"/check-in","POST",Map.of(),200);flow=request(base+"/participant-flow","GET",null,200);assertThat(flow.path("nextAction").asText()).isEqualTo("OPEN_WAITING_ROOM");assertThat(flow.path("checkIn").path("checkedInAt").asText()).isEqualTo(START.plusSeconds(600).toString());
  long revision=tournament(base).revision;when(clock.instant()).thenReturn(START.plusSeconds(610));request(base+"/check-in","POST",Map.of(),200);assertThat(tournament(base).revision).isEqualTo(revision);
  when(clock.instant()).thenReturn(START.plusSeconds(660));request(base+"/check-in","POST",Map.of(),400);ownedTournaments.expireTimelineCheckIns();assertThat(tournament(base).registrations.getFirst().status()).isEqualTo(TournamentRegistration.Status.CHECKED_IN);assertThat(tournament(base).participants).hasSize(1);assertThat(tournament(base).startedAt).isNull();
 }
 @Test void timelineCheckInRejectsMissingOfficialPassAndForeignOwner()throws Exception{
  String base=exam("DISQUALIFY");ready(base,130);freeze(base);when(clock.instant()).thenReturn(START.plusSeconds(600));request(base+"/check-in","POST",Map.of(),400);
  when(clock.instant()).thenReturn(START.plusSeconds(190));enqueue(base);finalDone(base);String registrationId=tournament(base).registrations.getFirst().id().toString();
  request("/api/auth/logout","POST",Map.of(),200);account=null;loginAccount();when(clock.instant()).thenReturn(START.plusSeconds(600));request(base+"/check-in","POST",Map.of("registrationId",registrationId),400);assertThat(tournament(base).registrations.getFirst().status()).isEqualTo(TournamentRegistration.Status.APPROVED);
 }
 @Test void missedTimelineCheckInIsPersistedOnceWithoutInventingMatches()throws Exception{
  String base=exam("DISQUALIFY");ready(base,130);freeze(base);enqueue(base);finalDone(base);when(clock.instant()).thenReturn(START.plusSeconds(660));
  var flow=request(base+"/participant-flow","GET",null,200);assertThat(flow.path("nextAction").asText()).isEqualTo("CHECK_IN_MISSED");request(base+"/check-in","POST",Map.of(),400);
  ownedTournaments.expireTimelineCheckIns();assertThat(tournament(base).registrations.getFirst().status()).isEqualTo(TournamentRegistration.Status.NOT_CHECKED_IN);assertThat(tournament(base).participants).isEmpty();assertThat(tournament(base).matches).isEmpty();long revision=tournament(base).revision;ownedTournaments.expireTimelineCheckIns();assertThat(tournament(base).revision).isEqualTo(revision);
  assertThat(request(base+"/notifications","GET",null,200).toString()).contains("CHECK_IN_MISSED");
 }
 @Test void managerCannotCloseCheckInOrStartBeforeTheTimelineWindow()throws Exception{
  String base=exam("DISQUALIFY");ready(base,130);freeze(base);enqueue(base);finalDone(base);when(clock.instant()).thenReturn(START.plusSeconds(600));
  request(base+"/close-registration","POST",Map.of(),400);request(base+"/close-check-in","POST",Map.of(),400);request(base+"/start","POST",Map.of(),400);assertThat(tournament(base).startedAt).isNull();
 }
 @Autowired FinalValidationService finalService;
 @Autowired FinalValidationStore finalStore;
 @Autowired CodingWorker worker;
 @Autowired CodingQueueStore queue;
 @Autowired FinalValidationWorker finalWorker;
 @Override com.fasterxml.jackson.databind.JsonNode done(String base)throws Exception{long until=System.nanoTime()+Duration.ofSeconds(10).toNanos();while(System.nanoTime()<until){worker.dispatchJobs();var w=request(base+"/workspace/me?language=PYTHON","GET",null,200);if(!Set.of("BUILDING","TESTING").contains(w.path("status").asText()))return w;Thread.sleep(25);}throw new AssertionError("Coding worker timeout");}
 String exam(String policy)throws Exception{String base=cupPolicy(true);var t=tournament(base);var s=t.timeline;var next=new TournamentTimeline(s.registrationOpenAt(),s.registrationCloseAt(),s.codingOpenAt(),s.codingCloseAt(),s.validationStartAt(),START.plusSeconds(600),START.plusSeconds(600),START.plusSeconds(660),START.plusSeconds(720),START.plusSeconds(780),null,s.deadlinePolicy(),TournamentTimeline.ValidationFailurePolicy.valueOf(policy));ownedTournaments.submissionMutation(t,com.rpsbattle.auth.AuthService.sessionAuthentication(account),()->{t.timeline=next;tournaments.changed(t);});return base;}
 com.fasterxml.jackson.databind.JsonNode enqueue(String base)throws Exception{when(clock.instant()).thenReturn(START.plusSeconds(190));finalService.process(id(base));return request(base+"/participant-flow","GET",null,200).path("finalValidation");}
 com.fasterxml.jackson.databind.JsonNode finalDone(String base)throws Exception{long until=System.nanoTime()+Duration.ofSeconds(10).toNanos();while(System.nanoTime()<until){finalService.process(id(base));worker.dispatchJobs();var flow=request(base+"/participant-flow","GET",null,200);var v=flow.path("finalValidation");if(Set.of("PASSED","FAILED","INFRA_ERROR").contains(v.path("status").asText())&&v.path("applied").asBoolean())return flow;Thread.sleep(30);}throw new AssertionError("Final validation timeout");}
 void hiddenFailure(){when(tests.hidden(any())).thenReturn(new BotTestService.HiddenResult(false,List.of(new BotTestService.HiddenCase("Hidden Test 1","FAIL"))));}
 @Test void finalValidationStartsAtScheduledTimeAndPassesOnlyTheFrozenArtifact()throws Exception{String base=exam("DISQUALIFY");var w=ready(base,130);freeze(base);when(clock.instant()).thenReturn(START.plusSeconds(190).minusNanos(1));finalService.process(id(base));assertThat(request(base+"/participant-flow","GET",null,200).path("finalValidation").isNull()).isTrue();var queued=enqueue(base);assertThat(queued.path("status").asText()).isEqualTo("QUEUED");assertThat(tournament(base).participants).isEmpty();var flow=finalDone(base);assertThat(flow.path("submissionStatus").asText()).isEqualTo("BOT_READY");assertThat(flow.path("finalValidation").path("versionId").asText()).isEqualTo(w.path("version").path("id").asText());assertThat(flow.path("finalValidation").path("steps").properties()).allMatch(e->e.getValue().asText().equals("PASS"));assertThat(tournament(base).participants).hasSize(1);assertThat(tournament(base).registrations.getFirst().status()).isEqualTo(TournamentRegistration.Status.APPROVED);submissions.requireLocked(id(base),tournament(base).registrations.getFirst().id().toString());assertThat(request(base+"/workspace/me?language=PYTHON","GET",null,200).path("sourceCode").asText()).contains("deadline source");}
 @Test void frozenButUnvalidatedBotCannotBypassTheOfficialExecutionGuard()throws Exception{String base=exam("DISQUALIFY");ready(base,130);freeze(base);assertThatThrownBy(()->submissions.requireLocked(id(base),tournament(base).registrations.getFirst().id().toString())).hasMessage("FINAL_VALIDATION_REQUIRED");}
 @Test void hiddenFailureDisqualifiesWithoutOpeningEditorOrLeakingHiddenInputs()throws Exception{String base=exam("DISQUALIFY");ready(base,130);freeze(base);hiddenFailure();enqueue(base);var flow=finalDone(base);assertThat(flow.path("submissionStatus").asText()).isEqualTo("VALIDATION_FAILED");assertThat(flow.path("canModifyWorkspace").asBoolean()).isFalse();assertThat(flow.toString()).doesNotContain("legalActions","sourceCode","debugOutput","Hidden Test");assertThat(request(base+"/submission/me","GET",null,200).path("status").asText()).isEqualTo("DISQUALIFIED");assertThat(tournament(base).participants).isEmpty();request(base+"/workspace/me/build","POST",Map.of("language","PYTHON","revision",0,"sourceCode","late"),409);}
 @Test void fallbackRevalidatesOlderVersionAndKeepsOriginalFreezeUnchanged()throws Exception{String base=exam("USE_LAST_VALID_VERSION");var first=ready(base,130);var second=ready(base,155);var frozen=freeze(base).path("frozenSubmission");when(tests.hidden(any())).thenAnswer(a->new BotTestService.HiddenResult(!((WorkspaceStore.Work)a.getArgument(0)).versionId().toString().equals(second.path("version").path("id").asText()),List.of()));enqueue(base);var flow=finalDone(base);assertThat(flow.path("submissionStatus").asText()).isEqualTo("BOT_READY");assertThat(flow.path("finalValidation").path("versionId").asText()).isEqualTo(first.path("version").path("id").asText());assertThat(flow.path("finalValidation").path("history")).hasSize(2);assertThat(flow.path("frozenSubmission")).isEqualTo(frozen);assertThat(request(base+"/submission/me","GET",null,200).path("versionId").asText()).isEqualTo(first.path("version").path("id").asText());}
 @Test void emergencyRequiresExplicitManagerReasonDeadlineAndRevisionAndRefreezesSeparately()throws Exception{String base=exam("ALLOW_EMERGENCY_RESUBMISSION");ready(base,130);var original=freeze(base).path("frozenSubmission");hiddenFailure();enqueue(base);var failed=finalDone(base).path("finalValidation");String path=base+"/final-validations/"+failed.path("id").asText()+"/emergency";long revision=tournament(base).revision;request(path,"POST",Map.of("revision",revision,"reason","x".repeat(401),"deadline",START.plusSeconds(250)),400);request(path,"POST",Map.of("revision",revision,"reason","","deadline",START.plusSeconds(250)),400);request(path,"POST",Map.of("revision",revision-1,"reason","Reviewed emergency request","deadline",START.plusSeconds(250)),409);request(path,"POST",Map.of("revision",revision,"reason","Reviewed emergency request","deadline",START.plusSeconds(250)),200);var flow=request(base+"/participant-flow","GET",null,200);assertThat(flow.path("canModifyWorkspace").asBoolean()).isTrue();assertThat(flow.path("codingCloseAt").asText()).isEqualTo(START.plusSeconds(250).toString());when(tests.hidden(any())).thenReturn(new BotTestService.HiddenResult(true,List.of()));when(clock.instant()).thenReturn(START.plusSeconds(220));var replacement=ready(base,220);when(clock.instant()).thenReturn(START.plusSeconds(250));finalService.process(id(base));flow=finalDone(base);assertThat(flow.path("submissionStatus").asText()).isEqualTo("BOT_READY");assertThat(flow.path("finalValidation").path("versionId").asText()).isEqualTo(replacement.path("version").path("id").asText());assertThat(submissions.frozenMine(id(base),account.id().value(),START.plusSeconds(180)).versionId().toString()).isEqualTo(original.path("versionId").asText());assertThat(jdbc.queryForObject("select count(*) from tournament_coding_freezes where tournament_id=?",Integer.class,UUID.fromString(id(base)))).isEqualTo(2);request(base+"/workspace/me","PUT",Map.of("language","PYTHON","revision",0,"sourceCode","late"),409);}
 @Test void infrastructureFailureCanRetryButDoesNotDisqualifyTheBot()throws Exception{String base=exam("DISQUALIFY");ready(base,130);freeze(base);when(tests.test(any())).thenThrow(new IllegalStateException("private infrastructure detail"));enqueue(base);var failed=finalDone(base).path("finalValidation");assertThat(failed.path("status").asText()).isEqualTo("INFRA_ERROR");assertThat(request(base+"/submission/me","GET",null,200).path("status").asText()).isEqualTo("LOCKED");var pass=new BotTestService.Result(true,"PUBLIC",List.of(),8,"PASS",0,0,1,"",Map.of());doReturn(pass).when(tests).test(any());request(base+"/final-validations/"+failed.path("id").asText()+"/retry","POST",Map.of("revision",tournament(base).revision,"reason","Sandbox available again"),200);assertThat(finalDone(base).path("submissionStatus").asText()).isEqualTo("BOT_READY");}
 @Test void artifactMutationFailsVerificationAndNeverApprovesRoster()throws Exception{String base=exam("DISQUALIFY");ready(base,130);freeze(base);doThrow(new WorkspaceSandbox.Failure("ARTIFACT_CHANGED")).when(sandbox).verify(any());enqueue(base);var flow=finalDone(base);assertThat(flow.path("finalValidation").path("reason").asText()).isEqualTo("ARTIFACT_CHANGED");assertThat(tournament(base).participants).isEmpty();}
 @Test void deadlineWithoutWorkerDoesNotInventAPass()throws Exception{String base=exam("DISQUALIFY");ready(base,130);freeze(base);when(clock.instant()).thenReturn(START.plusSeconds(600));finalService.process(id(base));var flow=finalDone(base);assertThat(flow.path("submissionStatus").asText()).isEqualTo("VALIDATION_INFRA_ERROR");assertThat(flow.path("finalValidation").path("reason").asText()).isEqualTo("VALIDATION_DEADLINE");assertThat(tournament(base).participants).isEmpty();}
 @Test void expiredLeaseIsReclaimedAndStaleWorkerCompletionCannotOverwriteSuccess()throws Exception{String base=exam("DISQUALIFY");ready(base,130);freeze(base);enqueue(base);var stale=queue.lease();assertThat(stale.finalValidationId()).isNotNull();jdbc.update("update bot_coding_jobs set lease_until=? where id=?",java.sql.Timestamp.from(Instant.now().minusSeconds(1)),stale.id());var fresh=queue.lease();assertThat(fresh.id()).isEqualTo(stale.id());assertThat(fresh.token()).isNotEqualTo(stale.token());finalWorker.run(fresh);finalService.process(id(base));queue.completeFinal(stale,false,false,"STALE_RESULT",Map.of("BUILD","FAIL"));assertThat(request(base+"/participant-flow","GET",null,200).path("finalValidation").path("status").asText()).isEqualTo("PASSED");}
 @Test void ordinaryUsersCannotReadOrControlAnotherOwnersFinalValidationDashboard()throws Exception{String base=exam("ALLOW_EMERGENCY_RESUBMISSION");ready(base,130);freeze(base);enqueue(base);var validation=finalDone(base).path("finalValidation").path("id").asText();request("/api/auth/logout","POST",Map.of(),200);account=null;loginAccount();request(base+"/final-validations","GET",null,403);request(base+"/final-validations/"+validation+"/emergency","POST",Map.of("revision",tournament(base).revision,"reason","Unauthorized","deadline",START.plusSeconds(250)),403);var own=request(base+"/participant-flow","GET",null,200);assertThat(own.path("finalValidation").isNull()).isTrue();assertThat(own.path("canModifyWorkspace").asBoolean()).isFalse();}
 @Test void queueBackPressureRollsBackAdmissionAndCanResumeWithoutDuplicateJobs()throws Exception{String base=exam("DISQUALIFY");ready(base,130);freeze(base);org.springframework.test.util.ReflectionTestUtils.setField(finalStore,"capacity",0);try{var v=enqueue(base);assertThat(v.isNull()).isTrue();}finally{org.springframework.test.util.ReflectionTestUtils.setField(finalStore,"capacity",200);}enqueue(base);assertThat(finalDone(base).path("submissionStatus").asText()).isEqualTo("BOT_READY");assertThat(jdbc.queryForObject("select count(*) from tournament_final_validations where tournament_id=?",Integer.class,UUID.fromString(id(base)))).isEqualTo(1);}
 @Test void workerResultAfterValidationDeadlineCannotBecomeTournamentReady()throws Exception{String base=exam("DISQUALIFY");ready(base,130);freeze(base);enqueue(base);var lease=queue.lease();when(clock.instant()).thenReturn(START.plusSeconds(600));finalWorker.run(lease);finalService.process(id(base));var flow=request(base+"/participant-flow","GET",null,200);assertThat(flow.path("submissionStatus").asText()).isEqualTo("VALIDATION_INFRA_ERROR");assertThat(tournament(base).participants).isEmpty();}
}
